# Dicionário didático dos indicadores: o que mede, fórmula, passo a passo, variáveis, fonte oficial e como ler
DPPO='domicílios particulares permanentes ocupados (DPPO, variável V0007)'
def censo(mede,formula,passos,vars_,tabela,ler):
    return dict(mede=mede,formula=formula,passos=passos,vars=vars_,fonte='IBGE – Censo Demográfico 2022, Agregados por Setores Censitários, tabela “'+tabela+'”',ler=ler)
DIC={
'ivsa':dict(mede='Grau de vulnerabilidade socioambiental relativa do setor, combinando carências de saneamento, renda, escolaridade e infraestrutura urbana.',
  formula='IVSA = 100 × Σ(wⱼ · z′ⱼ) / Σwⱼ',
  passos=['Para cada componente, calcula-se o valor do setor (ex.: % de domicílios sem esgoto na rede).','Normaliza-se de 0 a 1 entre os percentis 2 e 98 de todos os setores da RMVRC com 50 ou mais moradores: z = (x − P2) / (P98 − P2), limitado a 0 e 1. Renda entra em logaritmo.','Nos componentes em que valor alto é bom (esgoto, água, lixo, renda, árvores, pavimento) inverte-se: z′ = 1 − z.','Faz-se a média ponderada dos componentes com dado e multiplica-se por 100.','O setor só recebe índice se tiver 50+ moradores e dados para pelo menos 60% do peso total.'],
  vars='Sete componentes com peso 1: analfabetismo, esgoto, lixo, água, renda do responsável, arborização e pavimentação (ver quadro do IVSA).',fonte='Elaboração própria a partir do IBGE, Censo 2022',
  ler='0 = menor vulnerabilidade relativa na RMVRC; 100 = maior. É um índice relativo: compara setores entre si, não mede um padrão absoluto.'),
'pop':censo('Número de pessoas que moram no setor.','POP = V0001',['Lê-se diretamente a variável V0001 do arquivo “Básico”.'],'V0001 – total de pessoas','Básico','Base para os percentuais de pessoas e para as estimativas de moradores em áreas de risco.'),
'dens':censo('Concentração de moradores por área.','DENS = V0001 / ÁREA (hab./km²)',['Divide-se a população do setor pela área do setor informada pelo IBGE (AREA_KM2).'],'V0001 – pessoas; AREA_KM2 – área do setor na malha oficial','Básico e malha de setores','Valores altos indicam ocupação adensada; setores rurais têm densidades muito baixas.'),
'criancas':censo('Peso das crianças pequenas na população.','100 × (V01031 + V01032) / V0001',['Somam-se as pessoas de 0 a 4 anos (V01031) e de 5 a 9 anos (V01032).','Divide-se pelo total de pessoas e multiplica-se por 100.'],'V01031, V01032 – faixas etárias; V0001 – total de pessoas','Demografia','Setores com muitas crianças demandam creches, escolas e atenção básica.'),
'idosos':censo('Peso das pessoas idosas na população.','100 × (V01040 + V01041) / V0001',['Somam-se as pessoas de 60 a 69 anos (V01040) e de 70 anos ou mais (V01041).','Divide-se pelo total de pessoas e multiplica-se por 100.'],'V01040, V01041 – faixas etárias; V0001','Demografia','Idosos são mais sensíveis ao calor, a enchentes e à distância de serviços de saúde.'),
'negros':censo('Participação de pessoas pretas e pardas.','100 × (V01318 + V01320) / V0001',['Somam-se as pessoas que se declararam pretas (V01318) e pardas (V01320).','Divide-se pelo total de pessoas.'],'V01318 – preta; V01320 – parda; V0001','Cor ou raça','Indicador demográfico (neutro); usado para ler desigualdades em conjunto com renda e saneamento.'),
'indig':censo('Participação de pessoas indígenas (quesito cor ou raça).','100 × V01321 / V0001',['Divide-se o número de pessoas que se declararam indígenas pelo total.'],'V01321 – indígena; V0001','Cor ou raça','Indicador demográfico (neutro).'),
'mor':censo('Tamanho médio das famílias nos domicílios.','MOR = V0005',['Lê-se diretamente a média de moradores por '+DPPO+'.'],'V0005 – média de moradores em DPPO','Básico','Valores altos podem indicar adensamento domiciliar.'),
'agua':censo('Acesso à rede pública de abastecimento de água.','100 × V00111 / V0007',['Toma-se o número de DPPO cuja principal forma de abastecimento é a rede geral (V00111).','Divide-se pelo total de DPPO (V0007).'],'V00111 – usa rede geral; V0007 – total de DPPO','Características do domicílio 2','Quanto maior, melhor. Valores baixos indicam poço, nascente, carro-pipa etc.'),
'agua_enc':censo('Presença de água canalizada dentro da moradia.','100 × V00199 / V0007',['Toma-se o número de DPPO com água encanada até dentro da casa (V00199) e divide-se pelo total de DPPO.'],'V00199; V0007','Características do domicílio 2','Quanto maior, melhor.'),
'esgoto':censo('Acesso adequado ao esgotamento sanitário.','100 × (V00309 + V00310) / V0007',['Somam-se os DPPO com esgoto na rede geral ou pluvial (V00309) e com fossa séptica ligada à rede (V00310).','Divide-se pelo total de DPPO.'],'V00309, V00310; V0007','Características do domicílio 2','Quanto maior, melhor. Entra no IVSA de forma invertida (esgoto fora da rede).'),
'esg_prec':censo('Soluções precárias de esgoto.','100 × (V00312 + V00313 + V00314 + V00315 + V00316) / V0007',['Somam-se os DPPO com fossa rudimentar ou buraco (V00312), vala (V00313), rio, lago ou córrego (V00314), outra forma (V00315) e sem banheiro nem sanitário (V00316).','Divide-se pelo total de DPPO.'],'V00312 a V00316; V0007','Características do domicílio 2','Quanto maior, pior. Fossa séptica não ligada à rede não entra nem aqui nem em “esgoto na rede”.'),
'lixo':censo('Coleta regular de lixo.','100 × (V00397 + V00398) / V0007',['Somam-se os DPPO com lixo coletado no domicílio (V00397) e depositado em caçamba do serviço de limpeza (V00398).','Divide-se pelo total de DPPO.'],'V00397, V00398; V0007','Características do domicílio 2','Quanto maior, melhor.'),
'sem_banh':censo('Moradias sem banheiro exclusivo.','100 × V00495 / V0007',['Divide-se o número de DPPO sem banheiro de uso exclusivo com chuveiro e vaso (V00495) pelo total de DPPO.'],'V00495; V0007','Características do domicílio 2','Quanto maior, pior.'),
'renda':dict(mede='Rendimento mensal médio de quem responde pelo domicílio.',formula='RENDA = V06004 (R$)',passos=['Lê-se diretamente a média publicada pelo IBGE para os responsáveis com rendimento.'],vars='V06004 – rendimento nominal médio mensal das pessoas responsáveis com rendimento',fonte='IBGE – Censo 2022, Agregados por Setores, “Rendimento do responsável” (publicação de 2026)',ler='Valores de julho de 2022, sem correção. Médias são puxadas por rendas altas; compare com a mediana.'),
'renda_med':dict(mede='Rendimento mensal típico (mediano) do responsável.',formula='RENDA_MED = V06006 (R$)',passos=['Lê-se diretamente a mediana publicada pelo IBGE.'],vars='V06006 – rendimento nominal mediano mensal dos responsáveis com rendimento',fonte='IBGE – Censo 2022, “Rendimento do responsável”',ler='Metade dos responsáveis ganha menos que este valor.'),
'analf':censo('Pessoas de 15 anos ou mais que não sabem ler e escrever.','100 × V00901 / (V00900 + V00901)',['Toma-se o número de pessoas de 15+ anos que não sabem ler e escrever (V00901).','Divide-se pelo total de pessoas de 15+ anos (V00900 + V00901).'],'V00900 – sabe ler e escrever; V00901 – não sabe','Alfabetização','Quanto maior, pior. Componente do IVSA.'),
'arvore':censo('Presença de árvores na frente das moradias.','100 × (V05231 + V05232 + V05233) / V05200',['O IBGE percorreu as faces de quadra dos setores selecionados e registrou quantas árvores havia.','Somam-se os moradores em faces com 1 a 2 (V05231), 3 a 4 (V05232) e 5 ou mais árvores (V05233).','Divide-se pelo total de moradores pesquisados no entorno (V05200).'],'V05200 – moradores em DPPO do setor pesquisado; V05231–V05233','Entorno dos domicílios (moradores)','Quanto maior, melhor. Só existe para setores incluídos pelo IBGE na pesquisa de entorno (em geral urbanos).'),
'arv5':censo('Arborização densa na frente das moradias.','100 × V05233 / V05200',['Divide-se o número de moradores em faces com 5 ou mais árvores pelo total pesquisado.'],'V05233; V05200','Entorno dos domicílios','Quanto maior, melhor.'),
'pav':censo('Vias pavimentadas.','100 × V05206 / V05200',['Divide-se o número de moradores em faces com via pavimentada pelo total pesquisado no entorno.'],'V05206; V05200','Entorno dos domicílios','Quanto maior, melhor. Componente do IVSA.'),
'calcada':censo('Existência de calçada.','100 × V05221 / V05200',['Divide-se o número de moradores em faces com calçada pelo total pesquisado.'],'V05221; V05200','Entorno dos domicílios','Quanto maior, melhor.'),
'bueiro':censo('Drenagem de águas pluviais (bueiro ou boca de lobo).','100 × V05209 / V05200',['Divide-se o número de moradores em faces com bueiro pelo total pesquisado.'],'V05209; V05200','Entorno dos domicílios','Quanto maior, melhor. Ajuda a ler o risco de alagamento.'),
'luz':censo('Iluminação pública.','100 × V05212 / V05200',['Divide-se o número de moradores em faces com iluminação pública pelo total pesquisado.'],'V05212; V05200','Entorno dos domicílios','Quanto maior, melhor.'),
'onibus':censo('Ponto de ônibus ou van na face da quadra.','100 × V05215 / V05200',['Divide-se o número de moradores em faces com ponto de ônibus pelo total pesquisado.'],'V05215; V05200','Entorno dos domicílios','Quanto maior, melhor. Mede presença do ponto na própria face, não a oferta de linhas.'),
'app_pct':dict(mede='Parte do setor dentro de Áreas de Preservação Permanente de cursos d’água.',formula='100 × A(setor ∩ APP) / A(setor sem água)',passos=['Desenham-se as faixas do Código Florestal (Lei 12.651/2012, art. 4º) sobre a hidrografia: 100 m no Rio Cuiabá, 50 m no Coxipó, 30 m nos demais rios e córregos e em lagoas, 50 m de raio nas nascentes.','Convertem-se setor e faixas para uma grade fina (5 m).','Conta-se quantas células do setor (fora da água) estão na faixa e divide-se pelo total.'],vars='Hidrografia (rios, córregos, lagoas, nascentes) e polígono do setor',fonte='Lei 12.651/2012; hidrografia OpenStreetMap; setores IBGE',ler='Quanto maior, maior a ocupação potencial de APP. A lei municipal pode definir faixas diferentes em área urbana consolidada (Lei 14.285/2021).'),
'app_pop':dict(mede='Estimativa de moradores dentro de APP.',formula='POP × app_pct / 100',passos=['Multiplica-se a população do setor pela fração do setor em APP.'],vars='V0001; app_pct',fonte='Elaboração própria; IBGE',ler='Estimativa que supõe moradores distribuídos por igual no setor.'),
'inund':dict(mede='Parte do setor em terreno baixo e próximo da drenagem (suscetibilidade alta a inundação).',formula='100 × A(setor ∩ HAND alto) / A(setor)',passos=['Para cada ponto do terreno (modelo Copernicus GLO-30), calcula-se a altura acima da drenagem mais próxima para onde a água escoa (HAND).','Classe alta: até 2 m acima de córregos ou 4 m acima dos rios Cuiabá e Coxipó.','Mede-se a fração do setor nessa classe.'],vars='Modelo de superfície de 30 m e rede de drenagem derivada',fonte='Copernicus GLO-30 (ESA); método HAND (Rennó et al., 2008)',ler='É uma triagem. Onde há carta oficial do SGB, ela prevalece.'),
'inund_pop':dict(mede='Estimativa de moradores em suscetibilidade alta (HAND).',formula='POP × inund / 100',passos=['Multiplica-se a população pela fração do setor na classe alta.'],vars='V0001; inund',fonte='Elaboração própria',ler='Estimativa com ocupação uniforme.'),
'c1974':dict(mede='Parte do setor que ficaria abaixo do nível da cheia de 1974 do Rio Cuiabá.',formula='100 × A(setor ∩ mancha 1974) / A(setor)',passos=['Converte-se a leitura da régua de Cuiabá em 1974 (10,85 m) em altitude: 139,36 + 10,85 = 150,21 m.','Estende-se esse nível ao longo do rio seguindo a declividade da lâmina d’água, com ajuste de calibração de +2 m.','Marca-se o terreno abaixo desse nível e ligado ao rio; mede-se a fração do setor.'],vars='Cota da régua (ANA 66260001), modelo de terreno GLO-30',fonte='SUDEC-MT (cotas); ANA; Copernicus GLO-30',ler='Cenário histórico aplicado à cidade de hoje; desde 2000 a barragem de Manso reduz a frequência dessas cheias.'),
'c1974_pop':dict(mede='Estimativa de moradores dentro da mancha de 1974.',formula='POP × c1974 / 100',passos=['Multiplica-se a população pela fração do setor na mancha.'],vars='V0001; c1974',fonte='Elaboração própria',ler='Estimativa.'),
'sgb_alta':dict(mede='Parte do setor na classe alta da carta oficial de suscetibilidade a inundação.',formula='100 × A(setor ∩ classe alta SGB) / A(setor)',passos=['Os polígonos da carta (1:25.000) são convertidos para uma grade de 10 m.','Conta-se a fração das células do setor na classe alta.'],vars='Carta de Suscetibilidade a Movimentos Gravitacionais de Massa e Inundação',fonte='Serviço Geológico do Brasil (SGB/CPRM) – Cuiabá (2021) e Várzea Grande',ler='Referência oficial de suscetibilidade. Existe apenas para Cuiabá e Várzea Grande.'),
'sgb_alta_pop':dict(mede='Estimativa de moradores na classe alta da carta do SGB.',formula='POP × sgb_alta / 100',passos=['Multiplica-se a população pela fração do setor na classe alta.'],vars='V0001; sgb_alta',fonte='Elaboração própria; SGB',ler='Estimativa.'),
'a1974':dict(mede='Parte do setor abaixo do nível da cheia de 1974, recalculada com terreno sem vegetação.',formula='100 × A(setor ∩ mancha 1974 ANADEM) / A(setor)',passos=['Mesmo procedimento da cheia de 1974, mas com o modelo de terreno ANADEM (vegetação removida).','Ajuste de calibração recalculado para reproduzir os bairros atingidos: +2,5 m.'],vars='Cota da régua; MDT ANADEM 30 m',fonte='ANA/UFRGS (ANADEM); SUDEC-MT; ANA',ler='Versão refinada do cenário de 1974.'),
'a1974_pop':dict(mede='Moradores estimados na mancha de 1974 (ANADEM).',formula='POP × a1974 / 100',passos=['Multiplica-se a população pela fração do setor na mancha.'],vars='V0001; a1974',fonte='Elaboração própria',ler='Estimativa.'),
'alerta':dict(mede='Parte do setor abaixo do nível da cota de alerta da Defesa Civil.',formula='100 × A(setor ∩ mancha 8,50 m) / A(setor)',passos=['Converte-se a cota de alerta (8,50 m na régua) em altitude (147,86 m) e repete-se o procedimento da cheia de 1974.'],vars='Cota de alerta; modelo GLO-30',fonte='SUDEC-MT; ANA; Copernicus',ler='Áreas que começam a alagar primeiro.'),
'veg_nat':dict(mede='Quanto do setor é coberto por vegetação nativa.',formula='100 × Nnativa / (N − Nágua)',passos=['Usa-se o mapa anual de cobertura da terra do MapBiomas (2023, pixels de 30 m).','Contam-se os pixels do setor nas classes naturais: formação florestal, savânica, campestre, floresta alagável, campo alagado e restingas.','Divide-se pelo total de pixels do setor, excluídos rios e lagos.'],vars='Classes MapBiomas 3, 4, 5, 6, 11, 12, 49 e 50 (vegetação nativa); 31 e 33 (água)',fonte='MapBiomas – Coleção 9, ano 2023',ler='Quanto maior, mais vegetação nativa. Pastagem, lavoura, silvicultura e jardins urbanos não contam. Em setores urbanos pequenos o pixel de 30 m pode subestimar a arborização.'),
'erosao':dict(mede='Suscetibilidade natural do terreno à perda de solo pela água da chuva.',formula='V = (G + R + S + Vg + C) / 5',passos=['Cada tema recebe nota de 1 (estável) a 3 (vulnerável): G geologia, R relevo, S solo, Vg cobertura da terra, C clima (fixo em 2,0).','Calcula-se V em cada célula de 30 m.','O valor do setor é a média das células.'],vars='Geologia, geomorfologia e pedologia 1:250.000; cobertura MapBiomas',fonte='IBGE – BDiA (geologia, geomorfologia, pedologia); MapBiomas 2023; método Crepani et al. (INPE, 2001)',ler='1,0–1,3 estável; 1,4–1,7 moderadamente estável; 1,8–2,2 intermediário; 2,3–2,6 moderadamente vulnerável; 2,7–3,0 vulnerável.'),
'eros_alta':dict(mede='Parte do setor moderadamente vulnerável ou vulnerável à erosão.',formula='100 × N(V ≥ 2,25) / N(V)',passos=['Contam-se as células do setor com índice de erosão de 2,25 ou mais e divide-se pelo total de células com índice.'],vars='Índice V de erosão',fonte='Elaboração própria (Crepani et al., 2001)',ler='Quanto maior, maior a necessidade de cuidados com cortes de terreno, drenagem e cobertura do solo.'),
'verde':dict(mede='Parte do setor com vegetação densa vista por satélite.',formula='100 × N(NDVI ≥ 0,45) / (N − Nágua)',passos=['Calcula-se o NDVI em cada pixel de 10 m da imagem Sentinel-2 de 23/08/2026.','Contam-se os pixels com NDVI de 0,45 ou mais (vegetação densa na estiagem).','Divide-se pelo total de pixels do setor, fora da água.'],vars='Bandas B4 (vermelho) e B8 (infravermelho próximo)',fonte='Copernicus Sentinel-2 L2A (ESA)',ler='Quanto maior, melhor. Inclui qualquer vegetação verde (nativa, jardins, quintais).'),
'verde_hab':dict(mede='Quantos metros quadrados de vegetação existem no setor para cada morador.',formula='(Cobertura vegetal ÷ 100) × Área do setor (m²) ÷ Moradores',passos=['Parte-se da cobertura vegetal do setor (pixels Sentinel-2 com NDVI ≥ 0,45).','Multiplica-se a fração vegetada pela área do setor em m² para obter a área com vegetação.','Divide-se pelo número de moradores do Censo 2022. Setores com menos de 50 moradores ficam sem valor para não gerar números artificiais.','No município, soma-se a área vegetada de todos os setores e divide-se pela população total.'],vars='Cobertura vegetal (%), área do setor (IBGE), moradores (Censo 2022)',fonte='Copernicus Sentinel-2 L2A (ESA) + IBGE, Censo 2022',ler='Quanto maior, melhor. Mede toda a vegetação vista por satélite (inclui quintais e terrenos), não só praças e parques públicos; por isso não se compara diretamente com índices de áreas verdes públicas.'),
'ndvi':dict(mede='Vigor médio da vegetação no setor.',formula='NDVI = (B8 − B4) / (B8 + B4)',passos=['Calcula-se o índice em cada pixel de 10 m.','Faz-se a média dos pixels do setor, excluindo espelhos d’água.'],vars='B4 – vermelho (665 nm); B8 – infravermelho próximo (842 nm)',fonte='Copernicus Sentinel-2 L2A, 23/08/2026',ler='Vai de −1 a 1; acima de 0,45 indica vegetação densa; perto de 0, solo exposto ou superfície construída.'),
'lst':dict(mede='Temperatura média da superfície do setor (telhados, asfalto, solo, vegetação).',formula='LST (°C) = ST_B10 × 0,00341802 + 149,0 − 273,15',passos=['Usa-se o produto de temperatura de superfície do Landsat 9 (Coleção 2, Nível 2), banda ST_B10, de 13/08/2026 às 10h45.','Converte-se o valor digital em Kelvin (fator 0,00341802 e soma de 149,0) e em Celsius (−273,15).','Faz-se a média dos pixels de 30 m do setor.'],vars='Banda ST_B10',fonte='USGS – Landsat 9 Collection 2 Level-2',ler='Não é a temperatura do ar. Serve para comparar setores na mesma data e hora.'),
'lst_anom':dict(mede='Quanto o setor está mais quente ou mais frio que a média urbana.',formula='ΔT = LST do setor − 39,1 °C',passos=['Calcula-se a média da temperatura de superfície de todos os setores urbanos de Cuiabá e Várzea Grande (39,1 °C).','Subtrai-se essa média da temperatura do setor.'],vars='LST do setor; média urbana',fonte='Elaboração própria; Landsat 9',ler='Positivo = ilha de calor relativa; negativo = setor mais fresco que a média.'),
'd_ubs':dict(mede='Proximidade da unidade básica de saúde mais próxima.',formula='d = 2R · asin√[sin²(Δφ/2) + cos φ₁ · cos φ₂ · sin²(Δλ/2)]',passos=['Toma-se o centro geométrico (centróide) do setor.','Calcula-se a distância em linha reta (fórmula de Haversine, R = 6.371 km) até cada USF/UBS do CNES.','Fica a menor distância, arredondada a 10 m.'],vars='Coordenadas do centróide e dos estabelecimentos',fonte='CNES/DATASUS (Ministério da Saúde)',ler='Linha reta, não caminho pelas ruas nem tempo de viagem.'),
'd_saude':dict(mede='Proximidade da UPA, pronto-socorro ou hospital SUS mais próximo.',formula='d = min Haversine(centróide, estabelecimento)',passos=['Mesmo cálculo da distância à USF/UBS, com UPAs, prontos-socorros e hospitais que atendem SUS.'],vars='Coordenadas CNES',fonte='CNES/DATASUS',ler='Linha reta.'),
'd_esc':dict(mede='Proximidade da escola ou creche mais próxima.',formula='d = min Haversine(centróide, escola)',passos=['Mesmo cálculo, com escolas e creches mapeadas.'],vars='Coordenadas das escolas',fonte='OpenStreetMap (a ser substituído pelo Censo Escolar/INEP)',ler='Linha reta; a base colaborativa pode estar incompleta.'),
'd_parque':dict(mede='Proximidade de parque, praça ou reserva.',formula='d = min Haversine(centróide, área verde pública)',passos=['Mesmo cálculo, com parques, praças e reservas mapeados.'],vars='Coordenadas das áreas verdes',fonte='OpenStreetMap',ler='Linha reta; a base colaborativa pode estar incompleta.'),
}
